def can_fix_all_bugs_in_days(bugs, students, max_days, max_passes):
    bugs.sort()
    students.sort(key=lambda x: x[0])

    passes_used = 0
    bug_index = 0

    for day in range(max_days):
        if bug_index >= len(bugs):
            return True

        for student in students:
            if bug_index >= len(bugs):
                break
            if student[0] >= bugs[bug_index]:
                passes_used += student[1]
                if passes_used > max_passes:
                    return False
                bug_index += 1

    return bug_index >= len(bugs)

def find_min_days_to_fix_bugs(bugs, students, max_passes):
    left, right = 1, len(bugs)
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if can_fix_all_bugs_in_days(bugs, students, mid, max_passes):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

